CREATE TABLE IF NOT EXISTS source_registry (id TEXT PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, enabled INTEGER NOT NULL, configured INTEGER NOT NULL, user_enabled INTEGER, automation_allowed INTEGER, storage_allowed INTEGER, training_allowed INTEGER, disabled_reason TEXT, payload TEXT NOT NULL, last_attempt INTEGER, last_success INTEGER, last_error TEXT, next_allowed_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS source_request_usage (source_id TEXT NOT NULL REFERENCES source_registry(id), day TEXT NOT NULL, used INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(source_id,day));
CREATE TABLE IF NOT EXISTS http_response_cache (id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES source_registry(id), url TEXT NOT NULL, etag TEXT, modified TEXT, body TEXT NOT NULL, content_type TEXT, retrieved_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, retain_until INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS canonical_entities (id TEXT PRIMARY KEY, kind TEXT NOT NULL, name TEXT NOT NULL, wikidata_id TEXT UNIQUE, country TEXT, gender TEXT, payload TEXT NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS entity_aliases (id TEXT PRIMARY KEY, canonical_id TEXT NOT NULL REFERENCES canonical_entities(id), provider TEXT NOT NULL, provider_id TEXT NOT NULL, alias TEXT NOT NULL, normalized_alias TEXT NOT NULL, verified INTEGER NOT NULL DEFAULT 0, source_url TEXT, UNIQUE(provider,provider_id));
CREATE TABLE IF NOT EXISTS fixture_identities (fixture_id TEXT PRIMARY KEY REFERENCES fixtures(id), canonical_id TEXT NOT NULL, home_canonical TEXT REFERENCES canonical_entities(id), away_canonical TEXT REFERENCES canonical_entities(id), competition_canonical TEXT REFERENCES canonical_entities(id), verification TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS field_claims (id TEXT PRIMARY KEY, entity_id TEXT NOT NULL, entity_kind TEXT NOT NULL, field TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES source_registry(id), source_url TEXT NOT NULL, post_id TEXT, value_json TEXT NOT NULL, retrieved_at INTEGER NOT NULL, last_seen_at INTEGER NOT NULL, published_at INTEGER, known_at INTEGER NOT NULL, valid_to INTEGER, confidence REAL NOT NULL CHECK(confidence BETWEEN 0 AND 1), verification TEXT NOT NULL, license_ref TEXT NOT NULL, expires_at INTEGER NOT NULL, retain_until INTEGER NOT NULL, training_allowed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS evidence_conflicts (id TEXT PRIMARY KEY, entity_id TEXT NOT NULL, field TEXT NOT NULL, claims TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', detected_at INTEGER NOT NULL, resolved_at INTEGER);
CREATE TABLE IF NOT EXISTS verification_queue (id TEXT PRIMARY KEY, kind TEXT NOT NULL, entity_id TEXT, source_url TEXT, payload TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at INTEGER NOT NULL, resolved_at INTEGER, resolution TEXT);
CREATE TABLE IF NOT EXISTS social_accounts (id TEXT PRIMARY KEY, entity_id TEXT REFERENCES canonical_entities(id), platform TEXT NOT NULL, account_id TEXT NOT NULL, url TEXT NOT NULL, name TEXT NOT NULL, verified INTEGER NOT NULL DEFAULT 0, evidence_url TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES source_registry(id), retrieved_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, UNIQUE(platform,account_id));
CREATE TABLE IF NOT EXISTS social_evidence (id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES social_accounts(id), source_id TEXT NOT NULL REFERENCES source_registry(id), source_url TEXT NOT NULL, published_at INTEGER, retrieved_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, event_type TEXT NOT NULL, verification TEXT NOT NULL, confidence REAL NOT NULL, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS source_files (id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES source_registry(id), repository TEXT NOT NULL, path TEXT NOT NULL, url TEXT NOT NULL, season TEXT, year INTEGER, format TEXT NOT NULL, license_ref TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending', last_import INTEGER, fixture_count INTEGER NOT NULL DEFAULT 0, error TEXT, UNIQUE(repository,path));
CREATE TABLE IF NOT EXISTS prematch_snapshots (id TEXT PRIMARY KEY, fixture_id TEXT NOT NULL REFERENCES fixtures(id), kickoff_at INTEGER NOT NULL, horizon TEXT NOT NULL, target_at INTEGER NOT NULL, captured_at INTEGER NOT NULL, as_of INTEGER NOT NULL, status TEXT NOT NULL, evidence_ids TEXT NOT NULL, payload TEXT NOT NULL, UNIQUE(fixture_id,kickoff_at,horizon), CHECK(as_of < kickoff_at), CHECK(captured_at >= as_of));
CREATE TRIGGER IF NOT EXISTS immutable_snapshots_update BEFORE UPDATE ON prematch_snapshots BEGIN SELECT RAISE(ABORT,'Pre-match snapshots are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_snapshots_delete BEFORE DELETE ON prematch_snapshots BEGIN SELECT RAISE(ABORT,'Pre-match snapshots are immutable'); END;
CREATE TABLE IF NOT EXISTS calibration_models (id TEXT PRIMARY KEY, version TEXT NOT NULL, trained_at INTEGER NOT NULL, train_end INTEGER NOT NULL, validation_end INTEGER NOT NULL, test_start INTEGER NOT NULL, temperature REAL NOT NULL, payload TEXT NOT NULL, CHECK(train_end <= validation_end AND validation_end <= test_start));
CREATE TABLE IF NOT EXISTS update_jobs (id TEXT PRIMARY KEY, interval_ms INTEGER NOT NULL, last_attempt INTEGER, last_success INTEGER, next_run INTEGER NOT NULL DEFAULT 0, state TEXT NOT NULL DEFAULT 'pending', error TEXT, payload TEXT);
CREATE TABLE IF NOT EXISTS confederations (id TEXT PRIMARY KEY, name TEXT NOT NULL, region TEXT NOT NULL, source_url TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS country_confederations (country_id TEXT NOT NULL REFERENCES countries(id), confederation_id TEXT NOT NULL REFERENCES confederations(id), source_url TEXT NOT NULL, PRIMARY KEY(country_id,confederation_id));
CREATE INDEX IF NOT EXISTS idx_claims_entity_field ON field_claims(entity_id,field,valid_to,known_at);
CREATE INDEX IF NOT EXISTS idx_claims_cutoff ON field_claims(entity_kind,known_at,expires_at);
CREATE INDEX IF NOT EXISTS idx_claims_retention ON field_claims(retain_until);
CREATE INDEX IF NOT EXISTS idx_alias_name ON entity_aliases(normalized_alias,verified);
CREATE INDEX IF NOT EXISTS idx_fixture_canonical ON fixture_identities(canonical_id);
CREATE INDEX IF NOT EXISTS idx_source_files_pending ON source_files(source_id,state,year DESC);
CREATE INDEX IF NOT EXISTS idx_snapshot_fixture ON prematch_snapshots(fixture_id,as_of);
CREATE INDEX IF NOT EXISTS idx_social_date ON social_evidence(published_at DESC,expires_at);
CREATE INDEX IF NOT EXISTS idx_conflicts_entity ON evidence_conflicts(entity_id,status);
CREATE INDEX IF NOT EXISTS idx_verification_status ON verification_queue(status,created_at);
